<?php
namespace App\Http\Controllers;
use App\Services\DocumentIntegrationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MethodicalReportController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.reports'),403);}
public function annual(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$year=DB::table('academic_years')->where('id',$p->academic_year_id)->first();$periodIds=DB::table('academic_periods')->where('academic_year_id',$p->academic_year_id)->pluck('id');$data=['materials'=>DB::table('methodical_materials')->whereIn('academic_period_id',$periodIds)->count(),'approved'=>DB::table('methodical_materials')->whereIn('academic_period_id',$periodIds)->where('status','approved')->count(),'meetings'=>DB::table('methodical_meetings')->whereIn('academic_period_id',$periodIds)->count(),'observations'=>DB::table('lesson_observations')->whereIn('academic_period_id',$periodIds)->count(),'events'=>DB::table('methodical_events')->whereIn('academic_period_id',$periodIds)->count(),'development'=>DB::table('teacher_development_records')->whereBetween('ends_on',[$year->starts_on,$year->ends_on])->count(),'portfolio'=>DB::table('teacher_portfolio_items')->whereBetween('item_date',[$year->starts_on,$year->ends_on])->count()];$commissions=DB::table('methodical_commissions')->where('active',1)->get();return view('methodical.annual',compact('year','data','commissions'));}
public function meetingEdo(Request $r,$meeting,DocumentIntegrationService $docs){$this->manage($r);$p=$r->attributes->get('academic_period');$m=DB::table('methodical_meetings')->find($meeting);abort_if(!$m,404);$snapshot=['meeting'=>$m,'tasks'=>DB::table('methodical_tasks')->where('methodical_meeting_id',$meeting)->get()];$id=$docs->create($r->user(),$p->id,'methodical','meeting',$meeting,'protocol','Протокол '.($m->number?'№ '.$m->number.' ':'').$m->title,$snapshot,['summary'=>$m->agenda,'body'=>$m->minutes]);return redirect()->route('edo.show',$id);}
}